package sv.edu.udb.pokebattle.exception;
import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClientException; import java.time.LocalDateTime;
@RestControllerAdvice public class ApiExceptionHandler { record ErrorResponse(int estado,String error,String mensaje,LocalDateTime fecha){} private ErrorResponse e(HttpStatus h,String m){return new ErrorResponse(h.value(),h.getReasonPhrase(),m,LocalDateTime.now());} @ExceptionHandler(RecursoNoEncontradoException.class) @ResponseStatus(HttpStatus.NOT_FOUND) ErrorResponse n(RecursoNoEncontradoException x){return e(HttpStatus.NOT_FOUND,x.getMessage());} @ExceptionHandler(ConflictoException.class) @ResponseStatus(HttpStatus.CONFLICT) ErrorResponse c(ConflictoException x){return e(HttpStatus.CONFLICT,x.getMessage());} @ExceptionHandler(ReglaNegocioException.class) @ResponseStatus(HttpStatus.BAD_REQUEST) ErrorResponse r(ReglaNegocioException x){return e(HttpStatus.BAD_REQUEST,x.getMessage());} @ExceptionHandler(RestClientException.class) @ResponseStatus(HttpStatus.BAD_GATEWAY) ErrorResponse a(RestClientException x){return e(HttpStatus.BAD_GATEWAY,"No fue posible consultar PokéAPI");} }
